import math

def simpson(f,a,b,n=10000):
    h=(b-a)/n
    return h/3*(f(a)+f(b)+4*sum(f(a+i*h) for i in range(1,n,2))+2*sum(f(a+i*h) for i in range(2,n,2)))

k=1.0
z=simpson(lambda a: math.exp(k*math.cos(a)),0,2*math.pi)/(2*math.pi)
ea=simpson(lambda a: math.cos(a)*math.exp(k*math.cos(a)),0,2*math.pi)/(2*math.pi*z)
mi=k*ea-math.log(z)
print('Unit-circle vMF, k=1, tau=1: normalized loss for identity encoders =',-2*mi,'; constant encoders = 0')
